class Base {
public:
    int id;
};

// Virtual keyword prevents multiple Base subobjects
class Left : virtual public Base {};
class Right : virtual public Base {};

// Derived inherits one shared Base instance
class Derived : public Left, public Right {
public:
    Derived() {
        // Unambiguous access to the single shared Base::id
        id = 100;
    }
};

void example() {
    Derived d;
    // d.id refers to the single Base subobject
    d.id = 200;
}
